      "content": "{\n  \"name\": \"@linxin666/dsh-client-ui-task-board\",\n  \"description\": \"Host-authoritative task board for the DSH Web GUI with real session execution, Host cron scheduling, and optional cross-platform idle-sleep protection; mounted without DSH source changes.\",\n  \"version\": \"0.4.13\",\n  \"icon\": \"icon.svg\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/types/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/types/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": {\n      \"types\": \"./lib/types/client/index.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./src/*\": \"./src/*\",\n    \"./locale/en.json\": \"./locale/en.json\",\n    \"./locale/zh.json\": \"./locale/zh.json\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"dsh\": {\n    \"engines\": {\n      \"dsh\": \">=0.2.1-rc.3\"\n    },\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-connection\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-renderer\",\n        \"@deepseek-ai/dsh-client-ui-layout\",\n        \"@deepseek-ai/dsh-api-session-controller\",\n        \"@deepseek-ai/dsh-api-workspace-controller\",\n        \"@deepseek-ai/dsh-api-remotes\",\n        \"@deepseek-ai/dsh-client-ui-workspace\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"scripts\": {\n    \"build\": \"tsc -b tsconfig.build.json && tsdown\",\n    \"bundle\": \"tsdown\",\n    \"watch\": \"tsdown --watch\",\n    \"typecheck\": \"tsgo --noEmit\",\n    \"test\": \"vitest run\",\n    \"test:watch\": \"vitest\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/dsh\": \">=0.2.1-rc.3\",\n    \"react\": \"^18.2.0\"\n  },\n  \"dependencies\": {\n    \"@deepseek-ai/schemastery\": \"^3.18.5\",\n    \"marked\": \"^18.0.14\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.5\",\n    \"@deepseek-ai/dsh-agent\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-agent-preset-registry\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-attachment\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-api-gateway\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-api-remotes\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-api-session-controller\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-api-workspace-controller\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-connection\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-locale\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-store\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-layout\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-sidebar\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-workspace\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-commands\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-host-webserver\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-llm\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-settings\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-system-prompt\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-tools\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-workspace\": \"^0.2.1-rc.3\",\n    \"@types/node\": \"^22.20.0\",\n    \"@types/react\": \"~18.3.1\",\n    \"@types/react-dom\": \"^18.3.5\",\n    \"@vitest/coverage-v8\": \"^4.1.11\",\n    \"jsdom\": \"^25.0.0\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"^18.3.1\",\n    \"tsdown\": \"0.22.2\",\n    \"typescript\": \"~5.7.2\",\n    \"vitest\": \"^4.1.11\"\n  },\n  \"files\": [\n    \"lib/**/*.js\",\n    \"lib/**/*.js.map\",\n    \"lib/**/*.d.ts\",\n    \"lib/**/*.d.ts.map\",\n    \"src\",\n    \"cordis.patch.yml\",\n    \"icon.svg\",\n    \"locale\"\n  ],\n  \"license\": \"Apache-2.0\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"https://github.com/zhu1090093659/dsh-web.git\"\n  }\n}\n"
